{"perguntas":[
{"t":"multipla","p":"A quem os cristãos devem se sujeitar, segundo o início do capítulo?","o":["Às autoridades e governantes","Aos sacerdotes do templo","Aos anciãos de Jerusalém","Aos mestres da lei"],"c":0,"v":1,"e":"No versículo 1, Paulo pede que Tito os lembre de se sujeitar às autoridades e governantes."},
{"t":"multipla","p":"Como Paulo descreve o que \"nós\" éramos em outro tempo?","o":["Fiéis, mas fracos na fé","Insensatos, desobedientes e extraviados","Pobres e perseguidos","Sábios, mas orgulhosos"],"c":1,"v":3,"e":"O versículo 3 diz que em outro tempo éramos insensatos, desobedientes, extraviados, escravos de paixões e prazeres."},
{"t":"multipla","p":"Segundo o quê Deus nos salvou?","o":["Segundo as obras de justiça que realizamos","Segundo a nossa obediência à lei","Segundo a sua misericórdia","Segundo os nossos sacrifícios"],"c":2,"v":5,"e":"O versículo 5 diz que ele nos salvou não por meio das obras de justiça, mas segundo a sua misericórdia."},
{"t":"multipla","p":"Justificados pela graça de Deus, nós nos tornamos o quê?","o":["Seus servos","Seus mestres","Seus sacerdotes","Seus herdeiros"],"c":3,"v":7,"e":"O versículo 7 diz que, justificados pela sua graça, nos tornamos seus herdeiros, conforme a esperança da vida eterna."},
{"t":"multipla","p":"O que Paulo manda Tito evitar?","o":["Discussões inúteis, genealogias e debates sobre a lei","Viagens durante o inverno","Conversas com as autoridades","A prática de boas obras"],"c":0,"v":9,"e":"No versículo 9, Paulo manda evitar discussões inúteis, genealogias, contendas e debates sobre a lei, porque não trazem proveito."},
{"t":"cv","p":"Tito deve rejeitar o homem faccioso logo de início, sem admoestá-lo antes.","c":false,"v":10,"e":"O versículo 10 diz para rejeitá-lo depois de tê-lo admoestado uma ou duas vezes."},
{"t":"cv","p":"Paulo está resolvido a passar o inverno em Nicópolis e pede que Tito vá encontrá-lo lá.","c":true,"v":12,"e":"No versículo 12, Paulo pede que Tito se apresse a vir a Nicópolis, onde pretende passar o inverno."},
{"t":"cv","p":"Paulo pede que Tito cuide de Zenas e de Apolo, para que não lhes falte coisa alguma.","c":true,"v":13,"e":"O versículo 13 pede que Tito cuide com diligência de Zenas, o intérprete da lei, e de Apolo."}
]}

Tito 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Os homens mais velhos devem ser saudáveis em quê?","o":["Na oração, no jejum e na esmola","Na fé, no amor e na constância","Na palavra, no ensino e na disciplina","Na esperança, na paz e na alegria"],"c":1,"v":2,"e":"O versículo 2 diz que os mais velhos devem ser saudáveis na fé, no amor e na constância."},
 {"t":"multipla","p":"As mulheres mais velhas não devem ser escravizadas a quê?","o":["Às riquezas","Às vaidades","A muito vinho","À comida"],"c":2,"v":3,"e":"O versículo 3 diz que elas não devem ser caluniadoras nem escravizadas a muito vinho."},
 {"t":"multipla","p":"Qual é o motivo dado para a conduta ensinada às jovens?","o":["Para que a palavra de Deus não seja difamada","Para que recebam uma herança","Para que sejam honradas na cidade","Para que os maridos as louvem"],"c":0,"v":5,"e":"O versículo 5 termina dizendo que é para que a palavra de Deus não seja difamada."},
 {"t":"multipla","p":"Para que serve a palavra sadia e irrepreensível?","o":["Para que os jovens decorem a lei","Para que a igreja cresça em número","Para que os mais velhos sejam honrados","Para que o adversário seja envergonhado"],"c":3,"v":8,"e":"O versículo 8 diz que é para que o adversário seja envergonhado, sem ter nada de indigno a dizer."},
 {"t":"multipla","p":"Em vez de roubar, o que os servos devem demonstrar?","o":["Grande coragem","Toda a fidelidade","Muita sabedoria","Humildade nas palavras"],"c":1,"v":10,"e":"O versículo 10 diz que os servos não devem roubar, mas demonstrar toda a fidelidade."},
 {"t":"cv","p":"A graça de Deus nos ensina a renunciar à impiedade e às paixões mundanas.","c":true,"v":12,"e":"O versículo 12 diz que a graça nos ensina a renunciar à impiedade e às paixões mundanas."},
 {"t":"cv","p":"Cristo se entregou para purificar para si um povo indiferente às boas obras.","c":false,"v":14,"e":"O versículo 14 diz que esse povo é fervoroso em boas obras."},
 {"t":"cv","p":"Tito é orientado a declarar estas coisas, mas sem repreender ninguém.","c":false,"v":15,"e":"O versículo 15 manda declarar, exortar e também repreender com toda a autoridade."}
]}

Tito 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Ao falar da promessa da vida eterna, o que Paulo diz sobre Deus?","o":["Que nunca se cansa","Que não pode mentir","Que vê todas as coisas","Que não muda de ideia"],"c":1,"v":2,"e":"No versículo 2, a vida eterna foi prometida por Deus, \"que não pode mentir\"."},
 {"t":"multipla","p":"Como Paulo chama Tito na saudação da carta?","o":["Meu irmão amado","Meu companheiro de prisão","Meu verdadeiro filho na fé comum","Meu cooperador fiel"],"c":2,"v":4,"e":"No versículo 4, Paulo escreve \"a Tito, meu verdadeiro filho na fé comum\"."},
 {"t":"multipla","p":"Onde Paulo deixou Tito para constituir anciãos em cada cidade?","o":["Creta","Éfeso","Corinto","Macedônia"],"c":0,"v":5,"e":"No versículo 5, Paulo diz que deixou Tito em Creta para pôr em ordem o que restava e constituir anciãos."},
 {"t":"multipla","p":"Por que o bispo deve se manter apegado à palavra fiel?","o":["Para ser respeitado pelas autoridades","Para ensinar apenas os da circuncisão","Para escrever cartas às igrejas","Para exortar pela sã doutrina e convencer os que se opõem"],"c":3,"v":9,"e":"No versículo 9, o apego à palavra fiel serve para exortar pela sã doutrina e convencer os que se opõem."},
 {"t":"multipla","p":"Por qual motivo os enganadores ensinavam o que não deviam?","o":["Por medo","Por avareza","Por ignorância","Por inveja"],"c":1,"v":11,"e":"No versículo 11, eles ensinavam coisas que não deviam \"por avareza\"."},
 {"t":"cv","p":"Paulo diz que o testemunho do profeta cretense sobre os cretenses não é exato.","c":false,"v":13,"e":"No versículo 13, Paulo afirma: \"Este testemunho é exato\"."},
 {"t":"cv","p":"Segundo o capítulo, para os impuros e incrédulos todas as coisas são puras.","c":false,"v":15,"e":"No versículo 15, as coisas são puras para os puros, mas para os impuros e incrédulos \"nada é puro\"."},
 {"t":"cv","p":"Os que se opõem dizem conhecer a Deus, mas o negam por suas obras.","c":true,"v":16,"e":"No versículo 16, eles reconhecem que conhecem a Deus, mas o negam por suas obras."}
]}
